    long long key;
    uint32_t priority;
    int left, right;
    int count, size;
} Node;

static Node nodes[MAXN + 1];
static int node_count;
static uint32_t rng_state = 2463534242u;

static uint32_t random_priority(void) {
    rng_state ^= rng_state << 13;
    rng_state ^= rng_state >> 17;
    rng_state ^= rng_state << 5;
    return rng_state;
}

