    int child = nodes[root].left;
    nodes[root].left = nodes[child].right;
    nodes[child].right = root;
    update_size(root);
    update_size(child);
    return child;
}

static int rotate_left(int root) {
    int child = nodes[root].right;
    nodes[root].right = nodes[child].left;
    nodes[child].left = root;
    update_size(root);
    update_size(child);
    return child;
}

static int insert(int root, long long key) {
    if (!root) {
        int id = ++node_count;
        nodes[id].key = key;
        nodes[id].priority = random_priority();
        nodes[id].count = nodes[id].size = 1;
        return id;
