#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int child[2];
    int count;
} TrieNode;

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    size_t capacity = (size_t)n * 41 + 2;
    TrieNode *trie = calloc(capacity, sizeof(TrieNode));
    int nodes = 1;
    int previous_penalty = 0;

    for (int i = 0; i < n; ++i) {
        long long x, y;
        scanf("%lld %lld", &x, &y);

        x += previous_penalty;
        y += previous_penalty;

        long long distance = x * x + y * y;
        int node = 1;
        int penalty = 0;

        for (int bit = 40; bit >= 0; --bit) {
            int value = (int)((distance >> bit) & 1LL);

            if (value) {
                int left = trie[node].child[0];
                if (left) penalty += trie[left].count;
            }

            node = trie[node].child[value];
            if (!node) break;
        }

        if (node) penalty += trie[node].count;

        printf("%d\n", penalty);
        previous_penalty = penalty;

        node = 1;
        ++trie[node].count;

        for (int bit = 40; bit >= 0; --bit) {
            int value = (int)((distance >> bit) & 1LL);

            if (!trie[node].child[value])
                trie[node].child[value] = ++nodes;

            node = trie[node].child[value];
            ++trie[node].count;
        }
    }

    free(trie);
    return 0;
}
